with matched_keys as (select status, carrier from shipments intersect select status, carrier from shipments where status <> 'DELIVERED'), kept_rows as (select s.* from shipments s join matched_keys k on s.status = k.status and s.carrier = k.carrier) select s.order_id, s.carrier, s.shipped_date, s.delivered_date, s.cost, s.status, case when status rlike '^(LOST|DELIVERED)$' then 'EXTENDED' else 'GROUP_A' end as status_zone, (select avg(p2.amount) from payments p2 where p2.order_id = s.order_id) as avg_payment_amount from kept_rows s order by order_id desc;
